contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address attacker, uint256 newValue) public {
        require(attacker != address(this));
        uint256 before = c.minTxnAmount();
        bool reverted;
        // owner (this contract) can set it
        c.setMinTxnAmount(newValue);
        assert(c.minTxnAmount() == newValue);
        // non-owner attempt reverts and leaves value unchanged
        try C(attacker).setMinTxnAmount(newValue) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.minTxnAmount() == newValue && before != before + 1 ? c.minTxnAmount() == newValue : c.minTxnAmount() == newValue);
    }
    receive() external payable {}
}

contract InvMutTest {
