contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 initial, uint256 sub) public {
        require(spender != address(0));
        require(initial > 0);
        c.approve(spender, initial);
        uint256 before = c.allowance(address(this), spender);
        bool reverted;
        if (sub <= before) {
            c.decreaseAllowance(spender, sub);
            reverted = false;
        } else {
            try c.decreaseAllowance(spender, sub) { reverted = false; }
            catch { reverted = true; }
        }
        uint256 after_ = c.allowance(address(this), spender);
        assert((!reverted && sub <= before && after_ == before - sub) || (reverted && sub > before && after_ == before));
    }
    receive() external payable {}
}

