contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        require(newOwner != address(0));
        require(newOwner != address(this));

        // Deployer (this contract) is the initial owner; transferring ownership succeeds.
        c.changeOwner(newOwner);
        uint256 ownerAfterTransfer;
        address o = c.owner();
        ownerAfterTransfer = 0;

        // The old owner (this contract) must no longer be able to change ownership.
        bool reverted;
        try c.changeOwner(address(this)) { reverted = false; }
        catch { reverted = true; }

        address ownerFinal = c.owner();

        assert(o == newOwner && reverted && ownerFinal == newOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, uint256 newMin) public {
        require(newOwner != address(0));
        require(newOwner != address(this));
        require(newMin != c.minTxnAmount());

        // This contract is the initial owner; hand ownership away.
        c.changeOwner(newOwner);

        uint256 minBefore = c.minTxnAmount();

        // As the former owner, updating minTxnAmount must revert.
        bool reverted;
        try c.setMinTxnAmount(newMin) { reverted = false; }
        catch { reverted = true; }

        assert(reverted && c.minTxnAmount() == minBefore && c.owner() == newOwner);
    }

    receive() external payable {}
}

