contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, address recipient, uint256 amount) public {
        require(sender != address(0) && recipient != address(0));
        require(amount > 0);
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        bool reverted;
        // transfer must be a top-level call; use try/catch form via separate statement
        // We perform the call and capture revert flag using try/catch around an expression
        // is not allowed to nest; instead rely on low-level style via try is nested...
        // Use try with top-level call:
        bool ok;
        try c.transfer(recipient, amount) returns (bool r) { ok = r; reverted = false; }
        catch { reverted = true; }
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        assert(reverted && balSenderAfter == balSenderBefore && balRecipientAfter == balRecipientBefore);
    }
    receive() external payable {}
}

