contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, uint256 newRate) public {
        require(newOwner != address(0), "zero owner");
        require(newOwner != address(this), "same owner");

        // As deployer, this contract is the initial owner.
        address initialOwner = c.owner();
        require(initialOwner == address(this), "not deployer owner");

        // Owner changes ownership.
        c.changeOwner(newOwner);
        bool ownerChanged = (c.owner() == newOwner);

        // Former owner's privileged call now reverts.
        bool formerOwnerReverted;
        try c.setRewardRate(newRate) {
            formerOwnerReverted = false;
        } catch {
            formerOwnerReverted = true;
        }

        assert(ownerChanged && formerOwnerReverted);
    }
    receive() external payable {}
}

