contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, uint256 newRate) public {
        require(newOwner != address(0), "zero owner");
        require(newOwner != address(this), "same owner");

        require(c.owner() == address(this), "not deployer owner");

        c.changeOwner(newOwner);
        bool ownerChanged = (c.owner() == newOwner);

        bool formerOwnerReverted;
        // former owner (this contract) tries a restricted call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setRewardRate(uint256)", newRate));
        formerOwnerReverted = !ok;

        assert(ownerChanged && formerOwnerReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        uint256 supplyBefore = c.totalSupply();
        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipBalBefore = c.balanceOf(recipient);
        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 supplyAfter = c.totalSupply();
        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 recipBalAfter = c.balanceOf(recipient);
        assert(
            supplyAfter == supplyBefore &&
            (reverted ||
                (senderBalAfter + recipBalAfter == senderBalBefore + recipBalBefore &&
                 senderBalAfter <= senderBalBefore))
        );
    }
    receive() external payable {}
}

