contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 sub) public {
        require(spender != address(0));
        require(sub <= 2**128);
        // ensure the allowance is large enough so the call succeeds
        bool okApp = c.approve(spender, 2**200);
        require(okApp);
        uint256 allowanceBefore = c.allowance(address(this), spender);
        require(allowanceBefore >= sub);
        uint256 supplyBefore = c.totalSupply();
        bool ok = c.decreaseAllowance(spender, sub);
        uint256 allowanceAfter = c.allowance(address(this), spender);
        uint256 supplyAfter = c.totalSupply();
        assert(ok && allowanceAfter == allowanceBefore - sub && supplyAfter == supplyBefore);
    }
    receive() external payable {}
}

